INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Arquitecta sostenible", "en": "Sustainable architect", "source": "Sustainable architect"}, "biography": {"es": "Dise\u00f1o espacios de bajo impacto ambiental y jardines para barrios urbanos. Disfruto el senderismo y la fotograf\u00eda de arquitectura.", "en": "I design low-impact spaces and gardens for urban neighborhoods. I enjoy hiking and architectural photography.", "source": "I design low-impact spaces and gardens for urban neighborhoods. I enjoy hiking and architectural photography."}}', '6f837252172c53a88002c110ede4733a', '1988-01-12', 'Mujer', 'Medellín, Colombia', 'Medellín, Colombia', 'Sustainable architect', 'I design low-impact spaces and gardens for urban neighborhoods. I enjoy hiking and architectural photography.', '', 'https://example.invalid/valentina-rojas', '[]', '88e54dc9aac758e19031922388d572b8', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Ingeniero de sonido", "en": "Sound engineer", "source": "Sound engineer"}, "biography": {"es": "Grabo proyectos musicales independientes y trabajo en ac\u00fastica de estudios. Comparto rutas de ciclismo y sesiones de m\u00fasica en vivo.", "en": "I record independent music projects and work on studio acoustics. I share cycling routes and live music sessions.", "source": "I record independent music projects and work on studio acoustics. I share cycling routes and live music sessions."}}', 'b51915e29a445ee1971a96af89f87be7', '1989-02-13', 'Hombre', 'Bogotá, Colombia', 'Bogotá, Colombia', 'Sound engineer', 'I record independent music projects and work on studio acoustics. I share cycling routes and live music sessions.', '', 'https://example.invalid/mateo-silva', '[]', '3b0503f71b2251f2815fd6e3af15591d', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Dise\u00f1adora de producto", "en": "Product designer", "source": "Product designer"}, "biography": {"es": "Investigo c\u00f3mo hacer m\u00e1s accesibles los productos digitales. Me interesan la cer\u00e1mica, las bibliotecas y los viajes en tren.", "en": "I research ways to make digital products more accessible. I enjoy ceramics, libraries and train travel.", "source": "I research ways to make digital products more accessible. I enjoy ceramics, libraries and train travel."}}', '673b66dd7a2d56569464936f43445b7b', '1990-03-14', 'Mujer', 'Barranquilla, Colombia', 'Barranquilla, Colombia', 'Product designer', 'I research ways to make digital products more accessible. I enjoy ceramics, libraries and train travel.', '', 'https://example.invalid/samira-haddad', '[]', '0dc0d83745845de3b074a076bdecdde8', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Chef y emprendedor", "en": "Chef and entrepreneur", "source": "Chef and entrepreneur"}, "biography": {"es": "Dirijo una cocina de temporada con ingredientes de productores locales. Los fines de semana exploro mercados y nuevas recetas.", "en": "I run a seasonal kitchen using ingredients from local growers. On weekends I explore markets and new recipes.", "source": "I run a seasonal kitchen using ingredients from local growers. On weekends I explore markets and new recipes."}}', '69bc07dea39954c7ac2eee33ff4b43da', '1991-04-15', 'Hombre', 'São Paulo, Brasil', 'São Paulo, Brasil', 'Chef and entrepreneur', 'I run a seasonal kitchen using ingredients from local growers. On weekends I explore markets and new recipes.', '', 'https://example.invalid/thiago-costa', '[]', '4801c1e9bc9954cca8203c4cda3586b0', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
